// Provenance manifest for the secondary-experiment result records.
//
// The primary matrix stamps campaign_id per cell (bench/runner.mjs); the
// secondary experiments historically did not, so which measurement campaign a
// secondary result belongs to was only recoverable from repository history.
// This script derives that classification and writes it to a NEW file. It never
// edits an archived result: results/ is append-only.
//
// Classification evidence:
//   * a `<name>.pre-r5.bak` sibling means the record was regenerated by the r5
//     re-freeze campaign (scripts/r5-campaign.sh), which re-ran the primary
//     matrix and every secondary experiment;
//   * a `<name>-corrected*.json` sibling means the experiment was remeasured
//     after the MySQL state-reset defect was fixed, i.e. after the accepted
//     corrected-state campaign;
//   * absent a corrected sibling, the record predates that fix and carries the
//     pre-correction reset behaviour.
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const root = path.resolve(import.meta.dirname, "..");
const resultsDir = path.join(root, "results");
const repo = path.resolve(root, "..");

const git = (...args) =>
  execFileSync("git", ["-C", repo, ...args], { encoding: "utf8" }).trim();
const rel = (file) => path.posix.join("experiments/results", file);
const addedOn = (file) =>
  git("log", "--diff-filter=A", "--format=%ad", "--date=short", "-1", "--", rel(file)) || null;
const lastTouched = (file) =>
  git("log", "--format=%ad", "--date=short", "-1", "--", rel(file)) || null;

// The fourteen labelled secondary experiments, mapped to their result records.
const SECONDARY = [
  ["order-invariance", ["order-fwd.json", "order-rev.json"]],
  ["durability", ["durability.json", "raw-writes-relaxed.json"]],
  ["same-SQL", ["sameplan.json"]],
  ["open-loop", ["openloop.json", "openloop2.json"]],
  ["fan-out", ["fanout.json"]],
  ["equal-CPU", ["equalcpu.json"]],
  ["concurrency", ["scaling.json"]],
  ["utilization", ["utilization.postgres.json", "utilization.mysql.json"]],
  ["pool-size", ["poolsize.json", "poolsize.mysql.json"]],
  ["cluster", ["cluster.json"]],
  ["mixed-workload", ["mixed.json"]],
  ["wait-event", ["waitevents.json"]],
  ["post-restart", ["postreboot.json"]],
  ["longer-window-tail", ["taillong.json", "longrun.json", "longrun90.json"]],
  ["alternative-loading", ["altloading.json"]],
  ["transactional-write", ["txn-write.json"]],
];

const listing = fs.readdirSync(resultsDir);
const correctedSiblings = (file) => {
  const stem = file.replace(/\.json$/, "");
  const base = stem.replace(/\.(postgres|mysql)$/, "");
  return listing.filter((candidate) =>
    /corrected/.test(candidate)
    && candidate.endsWith(".json")
    && (candidate.startsWith(`${stem}-corrected`) || candidate.startsWith(`${base}-corrected`)));
};

const experiments = SECONDARY.map(([experiment, files]) => {
  const records = files.filter((file) => fs.existsSync(path.join(resultsDir, file)))
    .map((file) => {
      const corrected = correctedSiblings(file);
      const regeneratedByR5 = fs.existsSync(path.join(resultsDir, `${file}.pre-r5.bak`))
        || fs.existsSync(path.join(resultsDir, `${file.replace(/\.json$/, "")}.pre-r5.bak`));
      return {
        file,
        addedOn: addedOn(file),
        lastTouched: lastTouched(file),
        regeneratedByR5,
        correctedRemeasurements: corrected,
        campaign: corrected.length ? "remeasured-after-state-fix" : "r5-refreeze-pre-state-fix",
      };
    });
  const corrected = records.filter((r) => r.correctedRemeasurements.length).length;
  let campaign = "r5-refreeze-pre-state-fix";
  if (records.length === 0) campaign = "no-record-found";
  else if (corrected === records.length) campaign = "remeasured-after-state-fix";
  else if (corrected > 0) campaign = "mixed-see-records";
  return { experiment, records, campaign };
});

const missing = experiments.filter((e) => e.campaign === "no-record-found").map((e) => e.experiment);
const output = {
  note: "Derived provenance for secondary-experiment records. Archived results are append-only "
    + "and were not modified; this manifest is regenerated from repository history and from the "
    + "presence of .pre-r5.bak and -corrected sibling files. 'r5-refreeze-pre-state-fix' means the "
    + "record comes from the r5 re-freeze campaign and predates the MySQL AUTO_INCREMENT reset fix; "
    + "'remeasured-after-state-fix' means a corrected remeasurement exists. A pre-fix record is not "
    + "thereby invalid: the defect affected MySQL write, range-scan, and aggregation state, so "
    + "read-only PostgreSQL sensitivities are unaffected by it. Which records the manuscript uses as "
    + "clean evidence is stated in the manuscript, not here.",
  generatedFrom: "git history + results/ directory listing",
  headCommit: git("rev-parse", "--short", "HEAD"),
  experiments,
  missingRecords: missing,
  counts: {
    remeasuredAfterStateFix: experiments.filter((e) => e.campaign === "remeasured-after-state-fix").length,
    mixed: experiments.filter((e) => e.campaign === "mixed-see-records").length,
    r5PreStateFix: experiments.filter((e) => e.campaign === "r5-refreeze-pre-state-fix").length,
  },
};
fs.writeFileSync(
  path.join(resultsDir, "secondary-provenance.json"),
  JSON.stringify(output, null, 2) + "\n",
);
console.log(JSON.stringify(output.counts));
for (const e of experiments) console.log(`  ${e.campaign.padEnd(28)} ${e.experiment}`);
if (missing.length) console.log("missing records for:", missing.join(", "));
